package app.wasl.companion;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.provider.Settings;
import android.widget.*;
import android.text.InputType;
import java.util.*;
import org.json.*;

public class PaidActivity extends Activity {
 private EditText token;private TextView state,phones;private volatile boolean busy;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(28,36,28,28);body.setLayoutDirection(android.view.View.LAYOUT_DIRECTION_RTL);ScrollView scroll=new ScrollView(this);scroll.addView(body);AppUi.install(this,scroll);
  TextView title=new TextView(this);title.setText("قراءة Paid من واتساب بيزنس — تجريبي");title.setTextSize(22);body.addView(title);
  TextView info=new TextView(this);info.setText("هذه الأداة تقرأ أرقام عناوين المحادثات الظاهرة وبجوارها PAID فقط، أثناء جلسة تختارها لمدة 5 دقائق. افتح قائمة Paid ومرّر بنفسك، ثم ارجع لمراجعة الأرقام قبل إرسالها لوصل. لا تفتح المحادثات ولا ترسل رسائل. الأسماء المحفوظة بدون رقم ظاهر لا تُطابق. الدفعة جزئية وتحتاج اعتمادك في وصل حتى لو اخترت التلقائي. لم تُختبر القراءة على هاتف حقيقي بعد.");body.addView(info);
  token=new EditText(this);token.setHint("رمز واتساب من إعدادات وصل");token.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);token.setText(SyncClient.prefs(this).getString("paidToken",""));body.addView(token);
  button(body,"حفظ واختبار ربط واتساب",this::pair);
  button(body,"الأذونات وحل الإعدادات المقيّدة",()->startActivity(new Intent(this,PermissionsActivity.class)));
  button(body,"تفعيل إذن قارئ الشاشة",()->new AlertDialog.Builder(this).setTitle("إذن قراءة شاشة واتساب بيزنس").setMessage("التفعيل يتم منك داخل إعدادات أندرويد. الأداة مقيّدة بواتساب بيزنس، ولا تجمع إلا في جلسة تبدأها أنت. لا يمكنها قراءة واتساب وهو مقفول. افتح خدمة وصل — قراءة Paid وراجع وصف الإذن قبل تفعيلها.").setNegativeButton("إلغاء",null).setPositiveButton("فتح الإعدادات",(d,w)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).show());
  button(body,"ابدأ قراءة Paid لمدة 5 دقائق",()->{if(!readerEnabled()){state.setText("فعّل خدمة وصل — قراءة Paid من زر الإذن أولًا");return;}if(SyncClient.prefs(this).getString("paidToken","").isEmpty()){state.setText("اربط رمز واتساب أولًا");return;}new AlertDialog.Builder(this).setTitle("بدء جلسة جديدة؟").setMessage("ستستبدل الأرقام المحلية غير المرسلة. افتح Paid ومرّر القائمة بنفسك ثم ارجع هنا.").setNegativeButton("إلغاء",null).setPositiveButton("ابدأ",(d,w)->{SyncClient.prefs(this).edit().putStringSet("paidPhones",new HashSet<>()).remove("paidPending").putLong("paidUntil",System.currentTimeMillis()+300000L).putString("paidStatus","افتح قائمة Paid ومرّرها. الأرقام التي تحمل علامة PAID فقط ستظهر هنا.").apply();Intent launch=getPackageManager().getLaunchIntentForPackage("com.whatsapp.w4b");if(launch!=null)startActivity(launch);else{SyncClient.prefs(this).edit().putLong("paidUntil",0).apply();state.setText("واتساب بيزنس غير مثبت");}}).show();});
  button(body,"إيقاف القراءة وتحديث المعاينة",()->{SyncClient.prefs(this).edit().putLong("paidUntil",0).apply();show();});
  button(body,"إرسال الأرقام المعروضة لمراجعتها في وصل",this::send);
  button(body,"فتح تأكيدات واتساب في وصل",()->startActivity(new Intent(this,OrdersActivity.class)));
  state=new TextView(this);body.addView(state);phones=new TextView(this);phones.setTextDirection(android.view.View.TEXT_DIRECTION_LTR);phones.setTextIsSelectable(true);body.addView(phones);show();
 }
 private void button(LinearLayout body,String text,Runnable action){AppUi.button(this,body,text,()->{if(!busy)action.run();});}
 private boolean readerEnabled(){return PermissionsActivity.paidEnabled(this);}
 private void pair(){String key=token.getText().toString().trim();busy=true;state.setText("جارٍ اختبار رمز واتساب…");new Thread(()->{try{if(!key.matches("[a-fA-F0-9]{64}"))throw new Exception("انسخ رمز واتساب كاملًا من وصل");JSONObject reply=SyncClient.request("https://enchanted-ostrich-60.eu-west-1.convex.site",key,"/api/integrations/devices/health",null);if(!reply.optString("scope").equals("paid"))throw new Exception("هذا الرمز لأداة أخرى؛ أنشئ رمز واتساب من وصل");SyncClient.prefs(this).edit().putString("paidToken",key).putString("paidStatus","تم ربط واتساب. فعّل قارئ الشاشة ثم ابدأ جلسة قراءة.").apply();runOnUiThread(this::show);}catch(Exception e){runOnUiThread(()->state.setText(e.getMessage()));}finally{busy=false;}}).start();}
 private void show(){if(state==null)return;Set<String> captured=SyncClient.prefs(this).getStringSet("paidPhones",Collections.emptySet());ArrayList<String> sorted=new ArrayList<>(captured);Collections.sort(sorted);state.setText(SyncClient.prefs(this).getString("paidStatus","لم يتم الربط بعد")+"\nالأرقام المقروءة: "+sorted.size()+"\n"+(SyncClient.prefs(this).getLong("paidUntil",0)>System.currentTimeMillis()?"جلسة القراءة مفعلة؛ أوقفها بعد المراجعة":"القراءة متوقفة"));phones.setText(String.join("\n",sorted));}
 @Override public void onResume(){super.onResume();show();}
 private void send(){SyncClient.prefs(this).edit().putLong("paidUntil",0).apply();Set<String> captured=new TreeSet<>(SyncClient.prefs(this).getStringSet("paidPhones",Collections.emptySet()));if(captured.isEmpty()){state.setText("لا توجد أرقام مقروءة؛ لن تُرسل دفعة فارغة");return;}busy=true;state.setText("جارٍ حفظ دفعة المراجعة…");new Thread(()->{try{String pending=SyncClient.prefs(this).getString("paidPending","");JSONObject batch;if(pending.isEmpty()){batch=new JSONObject().put("eventId","android-paid:"+UUID.randomUUID()).put("phones",new JSONArray(captured)).put("unresolved",0).put("loaded",captured.size()).put("complete",false).put("observedAt",java.time.Instant.now().toString()).put("source","android-accessibility-paid");SyncClient.prefs(this).edit().putString("paidPending",batch.toString()).apply();}else batch=new JSONObject(pending);JSONObject reply=SyncClient.request("https://enchanted-ostrich-60.eu-west-1.convex.site",SyncClient.prefs(this).getString("paidToken",""),"/api/integrations/devices/paid",batch);JSONArray ack=reply.optJSONArray("acknowledged");boolean saved=false;if(ack!=null)for(int i=0;i<ack.length();i++)if(ack.getString(i).equals(batch.getString("eventId")))saved=true;if(!saved)throw new Exception("لم تصل إفادة حفظ الدفعة؛ أعد المحاولة");SyncClient.prefs(this).edit().putString("paidStatus","تم حفظ الدفعة للمراجعة في تأكيدات واتساب داخل وصل. الأرقام ذات الاسم المحفوظ لا تزال تحتاج مراجعة منفصلة.").putString("paidPending",batch.toString()).apply();runOnUiThread(this::show);}catch(Exception e){runOnUiThread(()->state.setText(e.getMessage()));}finally{busy=false;}}).start();}
}
